import fs from 'fs';
import os from 'os';
import path from 'path';
import { describe, expect, it, beforeEach, afterEach } from 'vitest';

import {
  getGlobalApiKey,
  getLocalApiKey,
  hasGlobalApiKey,
  hasLocalApiKey,
  setGlobalApiKey,
  setLocalApiKey
} from './key-store.js';
import { resolveGlobalConfigPath, resolveLocalEnvPath } from './paths.js';

describe('config key store', () => {
  let tmpCwd;
  let tmpHome;

  beforeEach(() => {
    tmpCwd = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-cwd-'));
    tmpHome = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-home-'));
  });

  afterEach(() => {
    fs.rmSync(tmpCwd, { recursive: true, force: true });
    fs.rmSync(tmpHome, { recursive: true, force: true });
  });

  it('handles local env api key lifecycle', () => {
    expect(hasLocalApiKey(tmpCwd)).toBe(false);
    expect(getLocalApiKey(tmpCwd)).toBeNull();

    setLocalApiKey('test-key', tmpCwd);

    expect(hasLocalApiKey(tmpCwd)).toBe(true);
    expect(getLocalApiKey(tmpCwd)).toBe('test-key');

    const envPath = resolveLocalEnvPath(tmpCwd);
    const content = fs.readFileSync(envPath, 'utf8');
    expect(content).toContain('OPENAI_API_KEY=test-key');
  });

  it('handles global config api key lifecycle', () => {
    expect(hasGlobalApiKey(tmpHome)).toBe(false);
    expect(getGlobalApiKey(tmpHome)).toBeNull();

    setGlobalApiKey('global-key', tmpHome);

    expect(hasGlobalApiKey(tmpHome)).toBe(true);
    expect(getGlobalApiKey(tmpHome)).toBe('global-key');

    const configPath = resolveGlobalConfigPath(tmpHome);
    const content = fs.readFileSync(configPath, 'utf8');
    expect(JSON.parse(content).OPENAI_API_KEY).toBe('global-key');
  });

  describe('local .env handling', () => {
    const writeEnv = (content) => fs.writeFileSync(resolveLocalEnvPath(tmpCwd), content);
    const readEnv = () => fs.readFileSync(resolveLocalEnvPath(tmpCwd), 'utf8');

    it('does not report a key when .env has none', () => {
      writeEnv('FOO=bar\n');
      expect(hasLocalApiKey(tmpCwd)).toBe(false);
      expect(getLocalApiKey(tmpCwd)).toBeNull();
    });

    it('treats an empty key as not configured', () => {
      writeEnv('OPENAI_API_KEY=\nexport OPENAI_API_KEY="" # empty\n');
      expect(hasLocalApiKey(tmpCwd)).toBe(false);
      expect(getLocalApiKey(tmpCwd)).toBeNull();
    });

    it.each([
      ['OPENAI_API_KEY=sk-1', 'sk-1'],
      ['export OPENAI_API_KEY="sk-1" # rotated', 'sk-1'],
      ["OPENAI_API_KEY='sk-1'#note", 'sk-1'],
      ['  OPENAI_API_KEY = sk-1   # note', 'sk-1'],
      ['OPENAI_API_KEY="sk #1"', 'sk #1'],
      ['OPENAI_API_KEY=sk-1\r', 'sk-1']
    ])('reads %j', (line, expected) => {
      writeEnv(`${line}\n`);
      expect(getLocalApiKey(tmpCwd)).toBe(expected);
    });

    it('ignores commented-out and similarly named definitions', () => {
      writeEnv('# OPENAI_API_KEY=old\nOPENAI_API_KEY_BACKUP=backup\n');
      expect(getLocalApiKey(tmpCwd)).toBeNull();
    });

    it('uses the last definition', () => {
      writeEnv('OPENAI_API_KEY=first\nOPENAI_API_KEY=second\n# OPENAI_API_KEY=commented\n');
      expect(getLocalApiKey(tmpCwd)).toBe('second');
    });

    it('appends the key and keeps every other line intact', () => {
      const original = '# comment\n\nFOO=bar\r\nexport BAZ="qux" # note\n';
      writeEnv(original);
      setLocalApiKey('sk-new', tmpCwd);
      expect(readEnv()).toBe(`${original}OPENAI_API_KEY=sk-new\r\n`);
      expect(getLocalApiKey(tmpCwd)).toBe('sk-new');
    });

    it('adds a line break before appending when the file lacks a trailing newline', () => {
      writeEnv('FOO=bar');
      setLocalApiKey('sk-new', tmpCwd);
      expect(readEnv()).toBe('FOO=bar\nOPENAI_API_KEY=sk-new\n');
    });

    it('updates the last definition in place, keeping export, quotes and comment', () => {
      writeEnv('A=1\nOPENAI_API_KEY=first\n\n# keep\nexport OPENAI_API_KEY="sk-old" # rotated\nB=2');
      setLocalApiKey('sk-new', tmpCwd);
      expect(readEnv()).toBe('A=1\nOPENAI_API_KEY=first\n\n# keep\nexport OPENAI_API_KEY="sk-new" # rotated\nB=2');
      expect(getLocalApiKey(tmpCwd)).toBe('sk-new');
    });

    it('updates unquoted and empty definitions', () => {
      writeEnv('export OPENAI_API_KEY=sk-old\n');
      setLocalApiKey('sk-new', tmpCwd);
      expect(readEnv()).toBe('export OPENAI_API_KEY=sk-new\n');

      writeEnv('OPENAI_API_KEY= # fill me\n');
      setLocalApiKey('sk-new', tmpCwd);
      expect(readEnv()).toBe('OPENAI_API_KEY=sk-new # fill me\n');
      expect(getLocalApiKey(tmpCwd)).toBe('sk-new');
    });

    it('creates .env with owner-only permissions and keeps existing permissions', () => {
      setLocalApiKey('sk-new', tmpCwd);
      expect(fs.statSync(resolveLocalEnvPath(tmpCwd)).mode & 0o777).toBe(0o600);

      fs.chmodSync(resolveLocalEnvPath(tmpCwd), 0o640);
      setLocalApiKey('sk-newer', tmpCwd);
      expect(fs.statSync(resolveLocalEnvPath(tmpCwd)).mode & 0o777).toBe(0o640);
    });

    it('rejects empty keys and keys with line breaks', () => {
      writeEnv('FOO=bar\n');
      expect(() => setLocalApiKey('', tmpCwd)).toThrow('API key is required');
      expect(() => setLocalApiKey('sk\nFOO=evil', tmpCwd)).toThrow();
      expect(readEnv()).toBe('FOO=bar\n');
    });
  });

  describe('global config handling', () => {
    const writeConfig = (content) => {
      fs.mkdirSync(path.dirname(resolveGlobalConfigPath(tmpHome)), { recursive: true });
      fs.writeFileSync(resolveGlobalConfigPath(tmpHome), content);
    };
    const readConfig = () => fs.readFileSync(resolveGlobalConfigPath(tmpHome), 'utf8');

    it('keeps other settings when saving a key', () => {
      writeConfig(JSON.stringify({ model: 'gpt-4o', OPENAI_API_KEY: 'old', nested: { a: 1 } }));
      setGlobalApiKey('sk-new', tmpHome);
      expect(JSON.parse(readConfig())).toEqual({ model: 'gpt-4o', OPENAI_API_KEY: 'sk-new', nested: { a: 1 } });
    });

    it('refuses to overwrite a config that is not valid JSON', () => {
      writeConfig('{ not json');
      expect(() => setGlobalApiKey('sk-new', tmpHome)).toThrow(/not valid JSON/);
      expect(readConfig()).toBe('{ not json');
    });

    it('only reports a non-empty key as configured', () => {
      writeConfig(JSON.stringify({ model: 'gpt-4o' }));
      expect(hasGlobalApiKey(tmpHome)).toBe(false);
      writeConfig(JSON.stringify({ OPENAI_API_KEY: '  ' }));
      expect(hasGlobalApiKey(tmpHome)).toBe(false);
      expect(getGlobalApiKey(tmpHome)).toBeNull();
    });

    it('creates the config with owner-only permissions', () => {
      setGlobalApiKey('sk-new', tmpHome);
      expect(fs.statSync(resolveGlobalConfigPath(tmpHome)).mode & 0o777).toBe(0o600);
    });
  });
});

