import fs from 'fs';

import { resolveGlobalConfigDir, resolveGlobalConfigPath, resolveLocalEnvPath } from './paths.js';

const API_KEY_NAME = 'OPENAI_API_KEY';

// Matches `[export ]OPENAI_API_KEY=` at the start of a line; group 1 is everything up to the value.
const ENV_DEFINITION_PATTERN = new RegExp(`^(\\s*(?:export\\s+)?${API_KEY_NAME}\\s*=\\s*)`);

const ensureDir = (dirPath) => {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true, mode: 0o700 });
  }
};

const normalizeKey = (key) => {
  const value = typeof key === 'string' ? key.trim() : '';
  if (!value) throw new Error('API key is required');
  if (/[\r\n]/.test(value)) throw new Error('API key must not contain line breaks');
  return value;
};

// Splits content into lines that keep their own terminator, so joining them reproduces the input exactly.
const splitLines = (content) => content.match(/[^\n]*\n|[^\n]+$/g) ?? [];

const stripLineEnding = (line) => {
  const match = line.match(/\r?\n$/);
  return match ? { body: line.slice(0, -match[0].length), ending: match[0] } : { body: line, ending: '' };
};

/**
 * Parses the value portion of a `.env` definition.
 * Returns the value and the [start, end) span it occupies within `raw` (quotes excluded).
 */
const parseEnvValue = (raw) => {
  const quote = raw[0];
  if (quote === '"' || quote === "'") {
    const closing = raw.indexOf(quote, 1);
    const rest = closing === -1 ? '' : raw.slice(closing + 1);
    if (closing !== -1 && /^\s*(#.*)?$/.test(rest)) {
      return { value: raw.slice(1, closing), start: 1, end: closing, quote };
    }
  }
  const commentMatch = raw.match(/(^|\s)#/);
  const uncommented = commentMatch ? raw.slice(0, commentMatch.index) : raw;
  const value = uncommented.trimEnd();
  return { value, start: 0, end: value.length, quote: null };
};

const findLastEnvDefinition = (lines) => {
  for (let index = lines.length - 1; index >= 0; index -= 1) {
    const { body, ending } = stripLineEnding(lines[index]);
    const match = body.match(ENV_DEFINITION_PATTERN);
    if (match) {
      const prefix = match[1];
      return { index, body, ending, prefix, parsed: parseEnvValue(body.slice(prefix.length)) };
    }
  }
  return null;
};

const formatEnvValue = (value, quote) => {
  if (quote && !value.includes(quote)) return value;
  if (!quote && /^[^\s#'"]+$/.test(value)) return value;
  return value.includes('"') ? `'${value}'` : `"${value}"`;
};

const readEnvFile = (envPath) => (fs.existsSync(envPath) ? fs.readFileSync(envPath, 'utf8') : null);

export const getLocalApiKey = (cwd = process.cwd()) => {
  const content = readEnvFile(resolveLocalEnvPath(cwd));
  if (content === null) return null;
  const definition = findLastEnvDefinition(splitLines(content));
  const value = definition?.parsed.value.trim();
  return value || null;
};

export const hasLocalApiKey = (cwd = process.cwd()) => Boolean(getLocalApiKey(cwd));

export const setLocalApiKey = (key, cwd = process.cwd()) => {
  const value = normalizeKey(key);
  const envPath = resolveLocalEnvPath(cwd);
  const content = readEnvFile(envPath) ?? '';
  const lines = splitLines(content);
  const definition = findLastEnvDefinition(lines);

  if (definition) {
    const { index, body, ending, prefix, parsed } = definition;
    const raw = body.slice(prefix.length);
    // Swap only the value, keeping the prefix, quotes and any trailing comment as they were.
    let before = raw.slice(0, parsed.start);
    let after = raw.slice(parsed.end);
    const formatted =formatEnvValue(value, parsed.quote);
    if (parsed.quote && formatted !== value) {
      before = '';
      after = after.slice(1);
    }
    if (after.startsWith('#')) {
      after = ` ${after}`;
    }
    lines[index] = `${prefix}${before}${formatted}${after}${ending}`;
  } else {
    const newline = content.includes('\r\n') ? '\r\n' : '\n';
    if (content && !content.endsWith('\n')) {
      lines.push(newline);
    }
    lines.push(`${API_KEY_NAME}=${formatEnvValue(value, null)}${newline}`);
  }

  fs.writeFileSync(envPath, lines.join(''), { encoding: 'utf8', mode: 0o600 });
  return envPath;
};

export const getGlobalApiKey = (homeDir = process.env.HOME || process.env.USERPROFILE) => {
  const configPath = resolveGlobalConfigPath(homeDir);
  if (!fs.existsSync(configPath)) return null;
  const content = fs.readFileSync(configPath, 'utf8');
  try {
    const parsed = JSON.parse(content);
    const value = parsed?.[API_KEY_NAME];
    return typeof value === 'string' && value.trim() ? value.trim() : null;
  } catch (error) {
    return null;
  }
};

